/// The built-in PBR material (`fynkel.pbr@1`): factors multiply the matching textures; an unbound texture behaves as white (normal: flat).
///
/// `fynkel.PbrMaterial` (record, id 0, 184 bytes).
class PbrMaterial implements WireRecord {
  const PbrMaterial({
    required this.baseColor,
    required this.metallic,
    required this.roughness,
    required this.emissive,
    required this.emissiveStrength,
    required this.normalScale,
    required this.occlusionStrength,
    required this.alphaMode,
    required this.alphaCutoff,
    required this.doubleSided,
    this.baseColorTexture,
    this.normalTexture,
    this.metallicRoughnessTexture,
    this.occlusionTexture,
    this.emissiveTexture,
  });

  /// Linear RGBA factor; multiplies `base_color_texture`.
  final Vec4 baseColor;
  /// `0` dielectric … `1` metal; multiplies the B channel of `metallic_roughness_texture`.
  final double metallic;
  /// `0` mirror … `1` fully rough; multiplies the G channel of `metallic_roughness_texture`.
  final double roughness;
  /// Linear RGB emitted light; multiplies `emissive_texture`.
  final Vec3 emissive;
  /// Scales `emissive`; values above 1 are HDR (`KHR_materials_emissive_strength`).
  final double emissiveStrength;
  /// Scales the tangent-space normal's XY.
  final double normalScale;
  /// `0` ignores the occlusion texture … `1` applies it fully.
  final double occlusionStrength;
  final AlphaMode alphaMode;
  /// Used by `mask` only.
  final double alphaCutoff;
  /// Draw both faces (no back-face culling); flips the normal on the back face.
  final bool doubleSided;
  /// sRGB colour texture.
  final AssetRef? baseColorTexture;
  /// Tangent-space normal map, OpenGL convention (+Y up), linear.
  final AssetRef? normalTexture;
  /// glTF packing, linear: G = roughness, B = metallic.
  final AssetRef? metallicRoughnessTexture;
  /// Ambient occlusion in R, linear.
  final AssetRef? occlusionTexture;
  /// sRGB emissive colour texture.
  final AssetRef? emissiveTexture;

  static const String schemaName = 'fynkel.PbrMaterial';
  static const int wireSize = 184;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeVec4(d, offset + 0, baseColor);
    d.setFloat32(offset + 16, metallic, Endian.little);
    d.setFloat32(offset + 20, roughness, Endian.little);
    writeVec3(d, offset + 24, emissive);
    d.setFloat32(offset + 36, emissiveStrength, Endian.little);
    d.setFloat32(offset + 40, normalScale, Endian.little);
    d.setFloat32(offset + 44, occlusionStrength, Endian.little);
    d.setUint32(offset + 48, alphaMode.index, Endian.little);
    d.setFloat32(offset + 52, alphaCutoff, Endian.little);
    d.setUint8(offset + 56, doubleSided ? 1 : 0);
    writeOptionalAssetRef(d, offset + 64, baseColorTexture, strings);
    writeOptionalAssetRef(d, offset + 88, normalTexture, strings);
    writeOptionalAssetRef(d, offset + 112, metallicRoughnessTexture, strings);
    writeOptionalAssetRef(d, offset + 136, occlusionTexture, strings);
    writeOptionalAssetRef(d, offset + 160, emissiveTexture, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static PbrMaterial decode(ByteData d, int offset, Uint8List tail) {
    return PbrMaterial(
      baseColor: readVec4(d, offset + 0),
      metallic: d.getFloat32(offset + 16, Endian.little),
      roughness: d.getFloat32(offset + 20, Endian.little),
      emissive: readVec3(d, offset + 24),
      emissiveStrength: d.getFloat32(offset + 36, Endian.little),
      normalScale: d.getFloat32(offset + 40, Endian.little),
      occlusionStrength: d.getFloat32(offset + 44, Endian.little),
      alphaMode: enumValue(AlphaMode.values, d.getUint32(offset + 48, Endian.little), 'fynkel.AlphaMode'),
      alphaCutoff: d.getFloat32(offset + 52, Endian.little),
      doubleSided: d.getUint8(offset + 56) != 0,
      baseColorTexture: readOptionalAssetRef(d, offset + 64, tail),
      normalTexture: readOptionalAssetRef(d, offset + 88, tail),
      metallicRoughnessTexture: readOptionalAssetRef(d, offset + 112, tail),
      occlusionTexture: readOptionalAssetRef(d, offset + 136, tail),
      emissiveTexture: readOptionalAssetRef(d, offset + 160, tail),
    );
  }

  @override
  bool operator ==(Object other) =>
      other is PbrMaterial && other.baseColor == baseColor && other.metallic == metallic && other.roughness == roughness && other.emissive == emissive && other.emissiveStrength == emissiveStrength && other.normalScale == normalScale && other.occlusionStrength == occlusionStrength && other.alphaMode == alphaMode && other.alphaCutoff == alphaCutoff && other.doubleSided == doubleSided && other.baseColorTexture == baseColorTexture && other.normalTexture == normalTexture && other.metallicRoughnessTexture == metallicRoughnessTexture && other.occlusionTexture == occlusionTexture && other.emissiveTexture == emissiveTexture;

  @override
  int get hashCode => Object.hashAll([baseColor, metallic, roughness, emissive, emissiveStrength, normalScale, occlusionStrength, alphaMode, alphaCutoff, doubleSided, baseColorTexture, normalTexture, metallicRoughnessTexture, occlusionTexture, emissiveTexture]);

  @override
  String toString() => 'PbrMaterial(baseColor: $baseColor, metallic: $metallic, roughness: $roughness, emissive: $emissive, emissiveStrength: $emissiveStrength, normalScale: $normalScale, occlusionStrength: $occlusionStrength, alphaMode: $alphaMode, alphaCutoff: $alphaCutoff, doubleSided: $doubleSided, baseColorTexture: $baseColorTexture, normalTexture: $normalTexture, metallicRoughnessTexture: $metallicRoughnessTexture, occlusionTexture: $occlusionTexture, emissiveTexture: $emissiveTexture)';
}
